import { Object3D, Mesh, PlaneGeometry, Color, Vector3 } from "three/webgpu";
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  mix,
  vec2,
  uv,
  texture,
  color,
  float,
  tslFn,
} from "three/tsl";
import { gsap } from "gsap";
import { createNode as applyPrimitive } from "@/primitives";
import { createTextMesh } from "@/text";

/**
 * @typedef {Object} NodeConfig
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Object} textContent
 * @property {Object} visual
 * @property {Object} placement
 * @property {Object} assets
 *
 * @typedef {Object} NodeContext
 * @property {Object<string,Function>} primitives
 * @property {Object} fontAtlas
 * @property {Function} textureLoader
 * @property {Function} glbLoader
 */

/**
 * Create the premium pricing card node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const root = new Object3D();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);
  root.name = "PremiumPricingCard";

  // ------------------------------
  // Card background plane
  // ------------------------------
  const cardW = 2.4;
  const cardH = 3.2;
  const cardGeom = new PlaneGeometry(cardW, cardH);
  const bgColor = new Color(0x16161d);
  const bgMaterial = new MeshBasicNodeMaterial({
    color: bgColor,
    side: 2, // DoubleSide
  });
  const bgMesh = new Mesh(cardGeom, bgMaterial);
  bgMesh.position.set(0, 0, 0);
  root.add(bgMesh);

  // ------------------------------
  // Header strip (machined metal)
  // ------------------------------
  const headerH = 0.08;
  const headerGeom = new PlaneGeometry(cardW, headerH);
  const headerMaterial = new MeshStandardNodeMaterial({
    color: new Color(0x16161d),
    metalness: float(0.5),
    roughness: float(0.55),
    clearcoat: float(0.2),
    clearcoatRoughness: float(0.1),
    anisotropy: float(0.6),
    side: 2,
  });
  const headerMesh = new Mesh(headerGeom, headerMaterial);
  headerMesh.position.set(0, cardH / 2 - headerH / 2, 0.001);
  root.add(headerMesh);

  // ------------------------------
  // Text elements (using fontAtlas)
  // ------------------------------
  const textGroup = new Object3D();
  root.add(textGroup);

  // Helper to create text mesh
  const makeText = (content, style, yPos) => {
    const mesh = createTextMesh(ctx.fontAtlas, content, {
      fontSize: style.fontSize,
      family: style.family,
      weight: style.fontWeight,
      letterSpacing: style.letterSpacing,
      lineHeight: style.lineHeight,
      color: style.color || "#e8ecf2",
    });
    mesh.position.set(0, yPos, 0.002);
    mesh.scale.set(1, 1, 1);
    return mesh;
  };

  // Typography definitions (converted to scene units)
  const tierStyle = {
    family: "JetBrains Mono",
    fontSize: 0.20, // 20px -> scene unit approx (20/100)
    fontWeight: 700,
    letterSpacing: 0.08,
    lineHeight: 1.2,
    color: "#e8ecf2",
  };
  const priceStyle = {
    family: "Lora",
    fontSize: 0.62,
    fontWeight: 600,
    letterSpacing: -0.01,
    lineHeight: 1,
    color: "#e8ecf2",
  };
  const captionStyle = {
    family: "JetBrains Mono",
    fontSize: 0.09,
    fontWeight: 400,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: "#e8ecf2",
  };
  const featureStyle = {
    family: "JetBrains Mono",
    fontSize: 0.13,
    fontWeight: 400,
    letterSpacing: 0,
    lineHeight: 1.5,
    color: "#e8ecf2",
  };
  const ctaStyle = {
    family: "JetBrains Mono",
    fontSize: 0.13,
    fontWeight: 700,
    letterSpacing: 0.08,
    lineHeight: 1,
    color: "#0b0b10",
  };

  // Vertical layout calculations
  const topMargin = cardH / 2 - 0.2; // start below top edge
  let curY = topMargin;

  const tierMesh = makeText("ATELIER RESERVE", tierStyle, curY);
  textGroup.add(tierMesh);
  curY -= tierStyle.fontSize * tierStyle.lineHeight + 0.05;

  const priceMesh = makeText("$480", priceStyle, curY);
  textGroup.add(priceMesh);
  curY -= priceStyle.fontSize * priceStyle.lineHeight + 0.03;

  const captionMesh = makeText("PER MONTH, BILLED ANNUALLY", captionStyle, curY);
  textGroup.add(captionMesh);
  curY -= captionStyle.fontSize * captionStyle.lineHeight + 0.5; // gap before features

  // Feature rows
  const featureTexts = [
    "Quarterly movement service",
    "Priority commission slots",
    "Private fitting lounge access",
    "Lifetime case refinishing",
  ];
  const featureRows = [];
  const featureRowHeight = 0.375;
  featureTexts.forEach((txt, idx) => {
    const rowY = curY - idx * (featureRowHeight + 0.006);
    const mesh = makeText(txt, featureStyle, rowY);
    textGroup.add(mesh);
    featureRows.push(mesh);
    // Hairline separator
    const sepGeom = new PlaneGeometry(cardW - 0.5, 0.006);
    const sepMat = new MeshBasicNodeMaterial({ color: new Color(0x23232b) });
    const sepMesh = new Mesh(sepGeom, sepMat);
    sepMesh.position.set(0, rowY - featureRowHeight / 2 - 0.003, 0.001);
    root.add(sepMesh);
  });

  curY = curY - featureTexts.length * (featureRowHeight + 0.006) - 0.5;

  // CTA button
  const ctaW = 1.4;
  const ctaH = 0.36;
  const ctaGeom = new PlaneGeometry(ctaW, ctaH);
  const gradientNode = tslFn(() => {
    const uvCoord = uv();
    const grad = mix(
      color(new Color("#ff4450")),
      color(new Color("#c1121f")),
      uvCoord.y
    );
    return grad;
  })();
  const ctaMaterial = new MeshBasicNodeMaterial({
    color: gradientNode,
    side: 2,
  });
  const ctaMesh = new Mesh(ctaGeom, ctaMaterial);
  ctaMesh.position.set(0, -cardH / 2 + ctaH / 2 + 0.5, 0.002);
  root.add(ctaMesh);

  // CTA label
  const ctaLabelMesh = makeText("JOIN THE RESERVE", ctaStyle, ctaMesh.position.y);
  root.add(ctaLabelMesh);

  // Emissive perimeter for CTA (simple outline using separate mesh)
  const outlineGeom = new PlaneGeometry(ctaW + 0.02, ctaH + 0.02);
  const outlineMat = new MeshBasicNodeMaterial({
    color: new Color(0xff2a38),
    emissive: new Color(0xff2a38),
    emissiveIntensity: 1.5,
    side: 2,
    transparent: true,
    opacity: 0.6,
  });
  const outlineMesh = new Mesh(outlineGeom, outlineMat);
  outlineMesh.position.copy(ctaMesh.position);
  root.add(outlineMesh);

  // ------------------------------
  // Interaction: CTA press animation
  // ------------------------------
  const timelines = [];

  const pressTimeline = gsap.timeline({ paused: true })
    .to(ctaMesh.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: "back.out(1.275)" })
    .to(ctaMesh.scale, { x: 1, y: 1, duration: 0.12, ease: "back.out(1.275)" });
  timelines.push(pressTimeline);

  // Attach handler (no DOM events, expose via userData)
  root.userData.handlers = {
    ctaPress: () => pressTimeline.restart(),
  };

  // ------------------------------
  // Entrance animations
  // ------------------------------
  // Weighted settle for whole card
  const settleTimeline = gsap.timeline();
  settleTimeline.from(root.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.9,
    ease: "power4.out",
  });
  timelines.push(settleTimeline);

  // Stagger feature rows fade-up
  const featureStagger = gsap.timeline({ delay: 0.3 });
  featureRows.forEach((row, i) => {
    row.material.transparent = true;
    row.material.opacity = 0;
    row.position.y += 0.2;
    featureStagger.to(
      row,
      {
        opacity: 1,
        y: "-=0.2",
        duration: 0.5,
        ease: "power2.out",
      },
      i * 0.08
    );
  });
  timelines.push(featureStagger);

  // ------------------------------
  // Apply cinematic primitives if any
  // ------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === "function") {
        fn(root, primitive.params);
      }
    });
  }

  // ------------------------------
  // Cleanup
  // ------------------------------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    bgGeom.dispose();
    bgMaterial.dispose();
    headerGeom.dispose();
    headerMaterial.dispose();
    ctaGeom.dispose();
    ctaMaterial.dispose();
    outlineGeom.dispose();
    outlineMat.dispose();
    // Dispose text meshes
    textGroup.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        obj.material?.dispose();
      }
    });
  };

  return root;
}
